import shutil
import openpyxl
from datetime import datetime

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = vals.active.title
vws = vals[sheet_name]
ws = wb[sheet_name]

def is_na(value):
    if value is None:
        return True
    if isinstance(value, str):
        s = value.strip()
        if s == "#N/A" or s.startswith("#"):
            return True
    return False

def normalize(value):
    if isinstance(value, str):
        s = value.strip()
        for fmt in (
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d",
            "%d/%m/%Y %H:%M:%S",
            "%d/%m/%Y",
            "%m/%d/%Y %H:%M:%S",
            "%m/%d/%Y",
        ):
            try:
                return datetime.strptime(s, fmt)
            except ValueError:
                pass
        return s
    return value

for row in range(2, 9):
    result = None
    for col in (1, 2, 3):
        value = vws.cell(row=row, column=col).value
        if not is_na(value):
            result = normalize(value)
            break

    ws.cell(row=row, column=4).value = result
    print(row, repr(result))

wb.save(OUT)
